#Requires -Version 5.1
<#
  Halcyon Installer — one-click WinForms installer for the Halcyon Discord client mod.

  Double-click (or run the built .exe) to open the GUI: detect every Discord flavor,
  inject / repair / uninstall the loader shim, and (optionally) register a per-user
  logon task that re-injects after Discord auto-updates itself.

  The renderer payload (halcyon.js) auto-updates from GitHub on every Discord launch —
  the shim's main process refreshes a per-user cache; the installer only seeds it.

  Runtime dependencies: NONE beyond what Windows ships (.NET + WinForms + PowerShell).
  Node is NOT required to run this — it is only the developer's build-time tool.

  Silent mode:  HalcyonInstaller.exe -EnsureInjected   (used by the logon task; no GUI)
#>
param([switch]$EnsureInjected, [switch]$SelfTest)

# ============================================================================
#  Engine — pure logic, no GUI. Defined as a scriptblock so it can be both
#  dot-sourced here AND shipped verbatim into the background worker runspace.
# ============================================================================
$Engine = {
    # Mirrors, tried in order. raw.githubusercontent.com is canonical but is the
    # first host a mainland network / DNS pollution / partial-proxy VPN breaks;
    # jsDelivr serves the same repo and gitmirror is a known-good CN mirror.
    $script:PayloadUrls    = @(
        'https://raw.githubusercontent.com/mzrodyu/CatieDiscordTools/main/dist/halcyon.js',
        'https://cdn.jsdelivr.net/gh/mzrodyu/CatieDiscordTools@main/dist/halcyon.js',
        'https://ghproxy.net/https://raw.githubusercontent.com/mzrodyu/CatieDiscordTools/main/dist/halcyon.js'
    )
    $script:PayloadUrl     = $script:PayloadUrls[0]
    $script:LastNetError   = $null
    # Explicit proxy: set by the GUI field, persisted to proxy.txt for the logon
    # task, or overridden per-run via HALCYON_PROXY. Empty = auto-detect.
    $script:PreferredProxy = $null
    $script:ProxyFile      = Join-Path (Join-Path $env:APPDATA 'Halcyon') 'proxy.txt'
    $script:Flavors        = @('Discord','DiscordPTB','DiscordCanary','DiscordDevelopment')
    $script:ProcNames      = @('Discord','DiscordPTB','DiscordCanary','DiscordDevelopment')
    $script:AppDataHalcyon = Join-Path $env:APPDATA 'Halcyon'
    $script:CacheFile      = Join-Path $script:AppDataHalcyon 'halcyon.js'
    $script:TaskName       = 'HalcyonKeepInjected'
    $script:Marker         = 'Generated by Halcyon'

    $script:ShimPackageJson = @'
{
  "name": "discord",
  "main": "index.js",
  "private": true
}
'@

    $script:ShimIndexJs = @'
// Generated by Halcyon. Do not edit; run the installer's Uninstall to remove.
"use strict";

const path = require("path");
const fs = require("fs");
const os = require("os");
const https = require("https");
const electron = require("electron");

const RESOURCES = path.join(__dirname, "..");
// The real Discord app was renamed to _app.asar; this shim IS resources/app.asar.
const ASAR = path.join(RESOURCES, "_app.asar");
const PRELOAD = path.join(__dirname, "preload.js");

// The auto-updated payload lives in a stable per-user dir: Discord installs each
// client update into a fresh app-<version> folder and discards our shim, but the
// %APPDATA%\Halcyon cache survives that.
//
// Two sources, tried in order. raw.githubusercontent.com is canonical, but it is
// also the first host a mainland network / DNS pollution / a VPN that only
// proxies SOME apps breaks — and this code runs in Discord's MAIN process, not
// the renderer. That distinction is the whole bug: Node's https ignores the
// Windows system proxy, so a Clash/v2ray "系统代理" setup made every update fail
// silently. Electron's net goes through Chromium's network stack and honours
// the system proxy / PAC, so it is the primary path; plain https stays as a
// fallback for TUN-mode setups and for when net is unavailable. jsDelivr
// mirrors the same repository and is reachable far more often from mainland
// networks than raw.githubusercontent.com.
const PAYLOAD_URLS = [
  "https://raw.githubusercontent.com/mzrodyu/CatieDiscordTools/main/dist/halcyon.js",
  "https://cdn.jsdelivr.net/gh/mzrodyu/CatieDiscordTools@main/dist/halcyon.js",
  "https://ghproxy.net/https://raw.githubusercontent.com/mzrodyu/CatieDiscordTools/main/dist/halcyon.js"
];

function cacheDir() {
  const base =
    process.env.APPDATA ||
    (process.platform === "darwin"
      ? path.join(os.homedir(), "Library", "Application Support")
      : process.env.XDG_CONFIG_HOME || path.join(os.homedir(), ".config"));
  return path.join(base, "Halcyon");
}

// Cheap sanity check before a download replaces a good cache. Error pages and
// proxy block screens are HTML; the payload is always JS that mentions its own
// name. The old check only looked at length, so a 1 KB+ error page could win.
function looksLikePayload(body) {
  if (!body || body.length < 20000) return false;
  try {
    return body.toString("utf8", 0, Math.min(body.length, 4096)).indexOf("Halcyon") !== -1;
  } catch (err) {
    return false;
  }
}

// The build stamps a /*! Halcyon vX.Y.Z */ banner. Mirrors can lag main
// by minutes, and a lagging response must never downgrade a newer cache.
function readVersion(body) {
  try {
    const head = body.toString("utf8", 0, Math.min(body.length, 4096));
    const m = /Halcyon v(d+.d+(?:.d+)?)/.exec(head);
    return m ? m[1] : null;
  } catch (err) {
    return null;
  }
}

function compareVersions(a, b) {
  const pa = a.split(".").map(Number);
  const pb = b.split(".").map(Number);
  const n = Math.max(pa.length, pb.length);
  for (let i = 0; i < n; i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d) return d;
  }
  return 0;
}

function writePayload(body, dest) {
  try {
    if (!looksLikePayload(body)) return;
    const incoming = readVersion(body);
    let current = null;
    try { current = readVersion(fs.readFileSync(dest)); } catch (err) {}
    if (current && (!incoming || compareVersions(incoming, current) <= 0)) return;
    const tmp = dest + "." + process.pid + ".tmp";
    fs.writeFileSync(tmp, body);
    fs.renameSync(tmp, dest); // atomic replace on Windows (MoveFileEx)
  } catch (err) {
    /* ignore — updating is best-effort */
  }
}

// Primary: Chromium's network stack (honours the Windows system proxy / PAC).
// Returns false when net is unavailable so the caller can fall back.
function fetchViaElectron(url, dest, next) {
  try {
    const { net } = electron;
    if (!net || typeof net.request !== "function") return false;
    let settled = false;
    let timer = null;
    const done = (advance) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      if (advance) next();
    };
    const req = net.request({ method: "GET", url, redirect: "follow" });
    req.setHeader("User-Agent", "Halcyon-Loader");
    req.on("response", (res) => {
      if (res.statusCode !== 200) {
        res.resume();
        done(true);
        return;
      }
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => {
        writePayload(Buffer.concat(chunks), dest);
        done(false);
      });
      res.on("error", () => done(true));
    });
    req.on("error", () => done(true));
    timer = setTimeout(() => {
      try { req.abort(); } catch (err) {}
      done(true);
    }, 12000);
    req.end();
    return true;
  } catch (err) {
    return false;
  }
}

// Fallback: plain Node https (no proxy support; works direct / TUN).
function fetchViaHttps(url, dest, hops, next) {
  const req = https.get(url, { headers: { "User-Agent": "Halcyon-Loader" } }, (res) => {
    const status = res.statusCode || 0;
    if (status >= 300 && status < 400 && res.headers.location && hops > 0) {
      res.resume();
      try {
        fetchViaHttps(new URL(res.headers.location, url).toString(), dest, hops - 1, next);
      } catch (err) {
        next();
      }
      return;
    }
    if (status !== 200) {
      res.resume();
      next();
      return;
    }
    const chunks = [];
    res.on("data", (c) => chunks.push(c));
    res.on("end", () => {
      writePayload(Buffer.concat(chunks), dest);
      next();
    });
    res.on("error", () => next());
  });
  req.on("error", () => next());
  req.setTimeout(10000, () => req.destroy());
}

// Fire-and-forget refresh of the cached payload for the NEXT launch. Never blocks
// boot, never throws: the renderer always runs whatever is already cached, so a
// slow or failed fetch just means "no update this time". Deferred off the boot
// path so a stalled socket can never compete with Discord starting up.
function refreshPayload() {
  try {
    const dir = cacheDir();
    fs.mkdirSync(dir, { recursive: true });
    const dest = path.join(dir, "halcyon.js");
    let index = 0;
    const tryNext = () => {
      if (index >= PAYLOAD_URLS.length) return;
      const url = PAYLOAD_URLS[index++];
      if (fetchViaElectron(url, dest, tryNext)) return;
      fetchViaHttps(url, dest, 3, tryNext);
    };
    tryNext();
  } catch (err) {
    /* best-effort */
  }
}

setTimeout(refreshPayload, 5000);

const { BrowserWindow } = electron;

// Force our preload onto Discord's real client windows — the ones that already
// carry a preload AND a title. Windows without those (splash, internal popups)
// are left untouched. NOT guarding here is one thing that breaks the window's own
// min/max/close controls; this mirrors how Vencord/Equicord patch.
class HalcyonBrowserWindow extends BrowserWindow {
  constructor(options) {
    if (!options || !options.webPreferences || !options.webPreferences.preload || !options.title) {
      super(options);
      return;
    }
    process.env.HALCYON_ORIGINAL_PRELOAD = options.webPreferences.preload;
    options.webPreferences.preload = PRELOAD;
    options.webPreferences.sandbox = false; // our preload needs fs / require
    super(options);
  }
}

// Copy the real BrowserWindow's static members and preserve its .name, then swap
// our subclass in as electron.BrowserWindow. Use a PLAIN object, NOT a Proxy: a
// Proxy over the electron module subtly breaks Discord's own window IPC and the
// min/max/close buttons stop responding. require.cache["electron"].exports is a
// getter-only accessor, so delete it before assigning.
Object.assign(HalcyonBrowserWindow, BrowserWindow);
Object.defineProperty(HalcyonBrowserWindow, "name", { value: "BrowserWindow", configurable: true });

try {
  const electronPath = require.resolve("electron");
  delete require.cache[electronPath].exports;
  require.cache[electronPath].exports = Object.assign({}, electron, { BrowserWindow: HalcyonBrowserWindow });
} catch (err) {
  console.error("[Halcyon] could not patch electron module:", err);
}

const realPackage = require(path.join(ASAR, "package.json"));
try {
  if (typeof electron.app.setAppPath === "function") electron.app.setAppPath(ASAR);
  electron.app.name = realPackage.name;
} catch (err) {
  console.error("[Halcyon] could not restore app identity:", err);
}

require(path.join(ASAR, realPackage.main));
'@

    $script:ShimPreloadJs = @'
// Generated by Halcyon. Do not edit; run the installer's Uninstall to remove.
"use strict";

const fs = require("fs");
const path = require("path");
const os = require("os");
const https = require("https");
const { webFrame, contextBridge } = require("electron");

// Discord's own preload path — chained AFTER we start the payload (below).
const original = process.env.HALCYON_ORIGINAL_PRELOAD;

// Cross-origin fetch relay for the payload. Discord's CSP (connect-src) blocks
// a page-context fetch to raw.githubusercontent.com, so the About page's update
// check asks this instead. Runs here in the preload (Node https) and is
// published on the MAIN world as window.HalcyonNative.fetchText.
function fetchText(url, hops) {
  return new Promise(function (resolve) {
    if (typeof url !== "string" || !/^https?:/i.test(url)) {
      resolve(null);
      return;
    }
    var req = https.get(
      url,
      { headers: { "User-Agent": "Halcyon-Update" }, timeout: 10000 },
      function (res) {
        var status = res.statusCode || 0;
        if (status >= 300 && status < 400 && res.headers.location && hops > 0) {
          res.resume();
          var next = new URL(res.headers.location, url).toString();
          resolve(fetchText(next, hops - 1));
          return;
        }
        if (status !== 200) {
          res.resume();
          resolve(null);
          return;
        }
        var data = "";
        res.setEncoding("utf8");
        res.on("data", function (chunk) {
          data += chunk;
          if (data.length > 1000000) {
            req.destroy();
            resolve(null);
          }
        });
        res.on("end", function () {
          resolve(data);
        });
        res.on("error", function () {
          resolve(null);
        });
      }
    );
    req.on("timeout", function () {
      req.destroy();
      resolve(null);
    });
    req.on("error", function () {
      resolve(null);
    });
  });
}

try {
  contextBridge.exposeInMainWorld("HalcyonNative", {
    fetchText: function (url) {
      return fetchText(url, 3);
    }
  });
} catch (err) {
  // contextIsolation is off: this preload already shares the page's world.
  try {
    var native = window.HalcyonNative || {};
    native.fetchText = function (url) {
      return fetchText(url, 3);
    };
    window.HalcyonNative = native;
  } catch (err2) {
    console.error("[Halcyon] could not expose fetchText:", err2);
  }
}

// 2. Load the payload. Prefer the auto-updated cache (refreshed by the main
//    process each launch); fall back to the copy shipped next to this shim so a
//    first run with no network still works. Reading a local file keeps startup
//    instant and offline-safe — the page itself never fetches (Discord's CSP
//    would block a cross-origin fetch anyway).
function cacheFile() {
  const base =
    process.env.APPDATA ||
    (process.platform === "darwin"
      ? path.join(os.homedir(), "Library", "Application Support")
      : process.env.XDG_CONFIG_HOME || path.join(os.homedir(), ".config"));
  return path.join(base, "Halcyon", "halcyon.js");
}

function readPayload() {
  const candidates = [cacheFile(), path.join(__dirname, "halcyon.js")];
  for (const p of candidates) {
    try {
      const code = fs.readFileSync(p, "utf8");
      if (code && code.length > 1024) return code;
    } catch (err) {
      // try the next candidate
    }
  }
  return null;
}

function inject() {
  const code = readPayload();
  if (!code) {
    console.error("[Halcyon] no payload available (cache empty, no bundled copy)");
    return;
  }
  // Run the payload in the page's MAIN world via webFrame.executeJavaScript. It
  // executes at document-start (before Discord's bundle, so Halcyon wins the
  // Webpack race) and is NOT subject to Discord's CSP — so, unlike a <script>
  // tag, no CSP stripping is needed. This is how Vencord/Equicord run their
  // renderer, and it avoids the CSP/Proxy tricks that broke the window controls.
  try {
    webFrame.executeJavaScript(code + "\n//# sourceURL=halcyon://payload");
  } catch (err) {
    console.error("[Halcyon] executeJavaScript failed:", err);
  }
}

inject();

// Now chain Discord's own preload so nothing it sets up is lost.
if (original) {
  try {
    require(original);
  } catch (err) {
    console.error("[Halcyon] Discord preload failed:", err);
  }
}
'@
    # Plugin payload embedded at build time (gzip+base64) so the installer works
    # with no network at all. The loader still auto-updates from GitHub at launch.
    $script:EmbeddedPayloadB64 = @'

'@

    function Get-EmbeddedPayloadBytes {
        try {
            if ([string]::IsNullOrEmpty($script:EmbeddedPayloadB64)) { return $null }
            $gz = [System.Convert]::FromBase64String(($script:EmbeddedPayloadB64 -replace '\s', ''))
            $in = New-Object System.IO.MemoryStream -ArgumentList (, $gz)
            $gzs = New-Object System.IO.Compression.GZipStream -ArgumentList $in, ([System.IO.Compression.CompressionMode]::Decompress)
            $out = New-Object System.IO.MemoryStream
            $gzs.CopyTo($out)
            $gzs.Dispose(); $in.Dispose()
            return $out.ToArray()
        } catch { return $null }
    }

    function Get-PayloadVersion {
        # Reads the `/*! Halcyon vX.Y.Z */` banner the build stamps at offset 0.
        # Old payloads predate the banner and return $null ("unknown, older").
        param($Bytes)
        try {
            if ($null -eq $Bytes -or $Bytes.Length -lt 32) { return $null }
            $n = [Math]::Min($Bytes.Length, 4096)
            $head = [System.Text.Encoding]::UTF8.GetString($Bytes, 0, $n)
            $m = [regex]::Match($head, 'Halcyon v(\d+(?:\.\d+){1,3})')
            if ($m.Success) { return [version]$m.Groups[1].Value }
        } catch {}
        return $null
    }

    function Test-PayloadBytes {
        # Never let an HTML error page / proxy block screen become the cache.
        param($Bytes)
        if ($null -eq $Bytes -or $Bytes.Length -lt 20000) { return $false }
        try {
            $n = [Math]::Min($Bytes.Length, 4096)
            return [System.Text.Encoding]::UTF8.GetString($Bytes, 0, $n).Contains('Halcyon')
        } catch { return $false }
    }

    function Write-CacheBytes {
        param([byte[]]$Bytes)
        if (-not (Test-Path -LiteralPath $script:AppDataHalcyon)) {
            New-Item -ItemType Directory -Path $script:AppDataHalcyon -Force | Out-Null
        }
        $tmp = $script:CacheFile + '.seed.tmp'
        [System.IO.File]::WriteAllBytes($tmp, $Bytes)
        if (Test-Path -LiteralPath $script:CacheFile) {
            # Replace() needs a REAL backup path under Windows PowerShell: the
            # overload takes a string, so a $null third argument is bound as ""
            # and throws "路径的格式不合法" — which the old code caught and
            # reported as "下载失败" even though the download itself succeeded.
            # That bug is why a working VPN still produced a failed update.
            $bak = $script:CacheFile + '.bak'
            [System.IO.File]::Replace($tmp, $script:CacheFile, $bak)
            Remove-Item -LiteralPath $bak -Force -ErrorAction SilentlyContinue
        } else {
            [System.IO.File]::Move($tmp, $script:CacheFile)
        }
    }

    function Ensure-Cache {
        # Seed %APPDATA%\Halcyon from the embedded copy when the cache is absent
        # OR older than the installer's embedded payload.
        #
        # The old version only seeded when the file was MISSING. Combined with a
        # failed download that meant: user runs a freshly built installer while
        # their network is flaky -> cache exists -> nothing happens -> they keep
        # running last month's payload and the fix "didn't ship". Compare the
        # version banners instead of just checking existence.
        $bytes = Get-EmbeddedPayloadBytes
        if ($null -eq $bytes -or -not (Test-PayloadBytes $bytes)) {
            return (Test-Path -LiteralPath $script:CacheFile)
        }
        $cacheExists = Test-Path -LiteralPath $script:CacheFile
        $embedded = Get-PayloadVersion $bytes
        $cached = $null
        if ($cacheExists) {
            try { $cached = Get-PayloadVersion ([System.IO.File]::ReadAllBytes($script:CacheFile)) } catch {}
        }
        $seed = $false
        if (-not $cacheExists) { $seed = $true }
        elseif ($null -eq $cached) { $seed = $true }   # pre-banner cache = older
        elseif ($null -ne $embedded -and $embedded -gt $cached) { $seed = $true }
        if (-not $seed) { return $true }
        try { Write-CacheBytes $bytes; return $true } catch { return $false }
    }

    function Write-Utf8NoBom {
        param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string]$Content)
        $enc = New-Object System.Text.UTF8Encoding($false)
        [System.IO.File]::WriteAllText($Path, $Content, $enc)
    }

    function Test-Injected {
        # Our injection: resources/app.asar is a DIRECTORY whose index.js carries
        # the marker; the original app is preserved next to it as _app.asar.
        param([Parameter(Mandatory)][string]$ResourcesPath)
        $idx = Join-Path (Join-Path $ResourcesPath 'app.asar') 'index.js'
        if (-not (Test-Path -LiteralPath $idx)) { return $false }
        try {
            $head = Get-Content -LiteralPath $idx -TotalCount 3 -ErrorAction Stop
            return (($head -join "`n").Contains($script:Marker))
        } catch { return $false }
    }

    function Test-ForeignShim {
        # app.asar replaced by a directory that is NOT ours (Vencord/Equicord/BD).
        param([Parameter(Mandatory)][string]$ResourcesPath)
        $asar = Join-Path $ResourcesPath 'app.asar'
        $isDir = $false
        try { $ai = Get-Item -LiteralPath $asar -ErrorAction SilentlyContinue; if ($ai -and $ai.PSIsContainer) { $isDir = $true } } catch {}
        if (-not $isDir) { return $false }
        return (-not (Test-Injected -ResourcesPath $ResourcesPath))
    }

    function Get-DiscordInstalls {
        $result = @()
        $root = $env:LOCALAPPDATA
        foreach ($flavor in $script:Flavors) {
            $base = Join-Path $root $flavor
            if (-not (Test-Path -LiteralPath $base)) { continue }
            $best = $null; $bestVer = $null
            Get-ChildItem -LiteralPath $base -Directory -Filter 'app-*' -ErrorAction SilentlyContinue | ForEach-Object {
                $v = $null
                if ([version]::TryParse($_.Name.Substring(4), [ref]$v)) {
                    if ($null -eq $bestVer -or $v -gt $bestVer) { $bestVer = $v; $best = $_ }
                }
            }
            if ($null -eq $best) { continue }
            $resources = Join-Path $best.FullName 'resources'
            $asar = Join-Path $resources 'app.asar'
            $orig = Join-Path $resources '_app.asar'
            # Valid install: has app.asar (vanilla file OR a mod's directory) or our _app.asar.
            if (-not (Test-Path -LiteralPath $asar) -and -not (Test-Path -LiteralPath $orig)) { continue }
            $result += [pscustomobject]@{
                Flavor        = $flavor
                Version       = $bestVer.ToString()
                ResourcesPath = $resources
                Injected      = (Test-Injected -ResourcesPath $resources)
                OtherMod      = (Test-ForeignShim -ResourcesPath $resources)
            }
        }
        return ,$result
    }
    function Get-ProxySpecs {
        # Order: explicit proxy (GUI field / proxy.txt / env) -> Windows system
        # proxy -> direct.
        #
        # 'system' = the Windows system proxy (Clash/v2ray "系统代理" sets this),
        # 'direct' = no proxy at all (TUN mode already routes everything).
        #
        # The old code used WebClient's default (system proxy) only. That is
        # fine when the VPN registers a system proxy, but a browser/extension
        # level proxy, a TUN-only client, or a proxy set only for the desktop
        # session leaves PowerShell with nothing — and the failure was swallowed
        # into "下载失败". An explicit value fixes those cases outright.
        $explicit = New-Object System.Collections.ArrayList
        if ($script:PreferredProxy) { [void]$explicit.Add($script:PreferredProxy) }
        try {
            if (Test-Path -LiteralPath $script:ProxyFile) {
                $fromFile = (Get-Content -LiteralPath $script:ProxyFile -Raw -ErrorAction Stop)
                if ($fromFile) { [void]$explicit.Add($fromFile.Trim()) }
            }
        } catch {}
        foreach ($name in @('HALCYON_PROXY','HTTPS_PROXY','https_proxy','HTTP_PROXY','http_proxy','ALL_PROXY','all_proxy')) {
            $v = [Environment]::GetEnvironmentVariable($name)
            if (-not [string]::IsNullOrWhiteSpace($v)) { [void]$explicit.Add($v.Trim()) }
        }
        $specs = New-Object System.Collections.ArrayList
        foreach ($p in $explicit) {
            if ([string]::IsNullOrWhiteSpace($p)) { continue }
            if ($p -notmatch '://') { $p = 'http://' + $p }
            if (-not $specs.Contains($p)) { [void]$specs.Add($p) }
        }
        if (-not $specs.Contains('system')) { [void]$specs.Add('system') }
        if (-not $specs.Contains('direct')) { [void]$specs.Add('direct') }
        return @($specs)
    }

    function Invoke-PayloadDownload {
        param([string]$Url, [string]$ProxySpec)
        try {
            $req = [System.Net.HttpWebRequest]::Create($Url)
            $req.UserAgent = 'Halcyon-Installer'
            $req.Timeout = 8000
            $req.ReadWriteTimeout = 12000
            $req.AllowAutoRedirect = $true
            $req.AutomaticDecompression = ([System.Net.DecompressionMethods]::GZip -bor [System.Net.DecompressionMethods]::Deflate)
            if ($ProxySpec -eq 'direct') {
                $req.Proxy = $null
            } elseif ($ProxySpec -eq 'system') {
                $req.Proxy = [System.Net.WebRequest]::GetSystemWebProxy()
            } else {
                $req.Proxy = New-Object System.Net.WebProxy($ProxySpec, $true)
            }
            $resp = $req.GetResponse()
            $stream = $resp.GetResponseStream()
            $ms = New-Object System.IO.MemoryStream
            try { $stream.CopyTo($ms) } finally { $stream.Dispose(); $resp.Dispose() }
            return $ms.ToArray()
        } catch {
            $script:LastNetError = $_.Exception.Message
            return $null
        }
    }

    function Update-PayloadCache {
        # Download the latest payload into the per-user cache (atomic). $true on success.
        # Every mirror x every proxy mode is tried; the first validated body wins.
        try {
            if (-not (Test-Path -LiteralPath $script:AppDataHalcyon)) {
                New-Item -ItemType Directory -Path $script:AppDataHalcyon -Force | Out-Null
            }
            try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
            $specs = Get-ProxySpecs
            $wanted = $null
            foreach ($url in $script:PayloadUrls) {
                foreach ($spec in $specs) {
                    $bytes = Invoke-PayloadDownload -Url $url -ProxySpec $spec
                    if (Test-PayloadBytes $bytes) { $wanted = $bytes; break }
                }
                if ($null -ne $wanted) { break }
            }
            if ($null -eq $wanted) { Ensure-Cache | Out-Null; return $false }
            # A lagging mirror can serve an older build than the cache (raw /
            # jsDelivr hold main for minutes). Never downgrade: if the fetched
            # payload is the same or older, keep what we already have.
            $newVer = Get-PayloadVersion $wanted
            $curVer = $null
            if (Test-Path -LiteralPath $script:CacheFile) {
                try { $curVer = Get-PayloadVersion ([System.IO.File]::ReadAllBytes($script:CacheFile)) } catch {}
            }
            if ($null -ne $curVer) {
                if ($null -eq $newVer) { return $true }              # pre-banner = older
                if ($newVer -le $curVer) { return $true }
            }
            Write-CacheBytes $wanted
            return $true
        } catch {
            $script:LastNetError = $_.Exception.Message
            Ensure-Cache | Out-Null
            return $false
        }
    }

    function Install-One {
        param([Parameter(Mandatory)]$Install, [switch]$Force)
        $res  = $Install.ResourcesPath
        $asar = Join-Path $res 'app.asar'
        $orig = Join-Path $res '_app.asar'
        if ((Test-ForeignShim -ResourcesPath $res) -and (-not $Force)) { return 'skipped-foreign' }
        $already = Test-Injected -ResourcesPath $res
        # Preserve the real app exactly once (rename app.asar -> _app.asar).
        if (-not (Test-Path -LiteralPath $orig)) {
            $ai = Get-Item -LiteralPath $asar -ErrorAction SilentlyContinue
            if ($ai -and -not $ai.PSIsContainer) { Move-Item -LiteralPath $asar -Destination $orig }
            else { return 'error: app.asar missing' }
        } else {
            # A stale app.asar file beside _app.asar — the real app is already saved.
            $ai = Get-Item -LiteralPath $asar -ErrorAction SilentlyContinue
            if ($ai -and -not $ai.PSIsContainer) { Remove-Item -LiteralPath $asar -Force }
        }
        if (-not (Test-Path -LiteralPath $asar)) { New-Item -ItemType Directory -Path $asar -Force | Out-Null }
        Write-Utf8NoBom -Path (Join-Path $asar 'package.json') -Content $script:ShimPackageJson
        Write-Utf8NoBom -Path (Join-Path $asar 'index.js')     -Content $script:ShimIndexJs
        Write-Utf8NoBom -Path (Join-Path $asar 'preload.js')   -Content $script:ShimPreloadJs
        if (Test-Path -LiteralPath $script:CacheFile) {
            try { [System.IO.File]::Copy($script:CacheFile, (Join-Path $asar 'halcyon.js'), $true) } catch {}
        } else {
            # No cache yet (offline / download failed): fall back to the embedded copy.
            $bytes = Get-EmbeddedPayloadBytes
            if ($null -ne $bytes -and $bytes.Length -gt 1024) {
                try { [System.IO.File]::WriteAllBytes((Join-Path $asar 'halcyon.js'), $bytes) } catch {}
            }
        }
        if ($already) { return 'updated' } else { return 'installed' }
    }

    function Uninstall-One {
        param([Parameter(Mandatory)]$Install)
        $res  = $Install.ResourcesPath
        $asar = Join-Path $res 'app.asar'
        $orig = Join-Path $res '_app.asar'
        if (-not (Test-Injected -ResourcesPath $res)) {
            if (Test-ForeignShim -ResourcesPath $res) { return 'left-foreign' }
            return 'not-present'
        }
        try {
            Remove-Item -LiteralPath $asar -Recurse -Force -ErrorAction Stop
            if (Test-Path -LiteralPath $orig) { Move-Item -LiteralPath $orig -Destination $asar }
            return 'removed'
        } catch { return ('error: ' + $_.Exception.Message) }
    }
    function Get-DiscordProcesses {
        Get-Process -ErrorAction SilentlyContinue | Where-Object { $script:ProcNames -contains $_.Name }
    }

    function Stop-DiscordProcesses {
        foreach ($p in (Get-DiscordProcesses)) { try { $p.Kill() } catch {} }
        for ($i = 0; $i -lt 25 -and (Get-DiscordProcesses); $i++) { Start-Sleep -Milliseconds 200 }
    }

    function Start-Discord {
        param([string]$Flavor = 'Discord')
        try {
            $update = Join-Path (Join-Path $env:LOCALAPPDATA $Flavor) 'Update.exe'
            if (Test-Path -LiteralPath $update) {
                Start-Process -FilePath $update -ArgumentList @('--processStart', ($Flavor + '.exe'))
            }
        } catch {}
    }

    function Get-SelfPath {
        # $PSCommandPath is populated when run as a .ps1 (dev); EMPTY inside a ps2exe
        # .exe, where the running module's file name is the exe we want to relaunch.
        if ($PSCommandPath) { return $PSCommandPath }
        try { return [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName } catch { return $null }
    }

    function Copy-SelfToStable {
        # The re-inject task must point at a STABLE path: a portable exe run from
        # Downloads can be moved/deleted, which would silently break re-injection.
        # Copy ourselves into %LOCALAPPDATA%\Halcyon and register that copy instead.
        param([Parameter(Mandatory)][string]$SelfPath)
        try {
            $dir = Join-Path $env:LOCALAPPDATA 'Halcyon'
            if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
            $dest = Join-Path $dir (Split-Path -Leaf $SelfPath)
            if ([System.IO.Path]::GetFullPath($SelfPath) -ne [System.IO.Path]::GetFullPath($dest)) {
                [System.IO.File]::Copy($SelfPath, $dest, $true)
            }
            return $dest
        } catch { return $SelfPath }
    }

    function Register-KeepInjected {
        param([Parameter(Mandatory)][string]$SelfPath)
        $isExe = $SelfPath -match '\.exe$'
        if ($isExe) {
            $prog = $SelfPath; $argStr = '-EnsureInjected'
            $runCmd = '"' + $SelfPath + '" -EnsureInjected'
        } else {
            $prog = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
            $argStr = '-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File "' + $SelfPath + '" -EnsureInjected'
            $runCmd = '"' + $prog + '" ' + $argStr
        }
        try {
            $action  = New-ScheduledTaskAction -Execute $prog -Argument $argStr
            $trigger = New-ScheduledTaskTrigger -AtLogOn
            try {
                $rep = (New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1) -RepetitionInterval (New-TimeSpan -Minutes 30)).Repetition
                $trigger.Repetition = $rep
            } catch {}
            $settings  = New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries
            $principal = New-ScheduledTaskPrincipal -UserId $env:USERNAME -LogonType Interactive -RunLevel Limited
            Register-ScheduledTask -TaskName $script:TaskName -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Force -ErrorAction Stop | Out-Null
            return 'scheduled-task'
        } catch {
            try {
                New-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run' -Name $script:TaskName -Value $runCmd -PropertyType String -Force | Out-Null
                return 'run-key'
            } catch { return 'failed' }
        }
    }
    function Unregister-KeepInjected {
        try { Unregister-ScheduledTask -TaskName $script:TaskName -Confirm:$false -ErrorAction SilentlyContinue | Out-Null } catch {}
        try {
            $runKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
            if (Get-ItemProperty -LiteralPath $runKey -Name $script:TaskName -ErrorAction SilentlyContinue) {
                Remove-ItemProperty -LiteralPath $runKey -Name $script:TaskName -ErrorAction SilentlyContinue
            }
        } catch {}
    }

    function Invoke-EnsureInjected {
        # Silent, idempotent — for the logon task. Never kills or launches Discord.
        Ensure-Cache | Out-Null
        if (-not (Test-Path -LiteralPath $script:CacheFile)) { Update-PayloadCache | Out-Null }
        foreach ($i in (Get-DiscordInstalls)) {
            if (-not $i.Injected) { Install-One -Install $i | Out-Null }
        }
    }

    function Get-Diagnostics {
        $installs = @(Get-DiscordInstalls)
        $node = Get-Command node -ErrorAction SilentlyContinue
        if ($node) { $nodeStr = 'found (' + $node.Source + ')' } else { $nodeStr = 'not found - not required' }
        if (Test-Path -LiteralPath $script:CacheFile) {
            $kb = [math]::Round(((Get-Item -LiteralPath $script:CacheFile).Length / 1KB))
            $cacheStr = ('' + $kb + ' KB')
        } else { $cacheStr = 'none yet' }
        $emb = Get-EmbeddedPayloadBytes
        if ($emb) { $embStr = ([math]::Round($emb.Length / 1KB)).ToString() + ' KB' } else { $embStr = 'none' }
        return ('Discord: ' + $installs.Count + '  |  PowerShell ' + $PSVersionTable.PSVersion.ToString() + '  |  Node: ' + $nodeStr + '  |  cache: ' + $cacheStr + '  |  builtin: ' + $embStr)
    }
}

# ============================================================================
#  Worker — runs inside the background runspace. Uses engine functions + $Sync.
#  (Never touches WinForms controls — the UI drains $Sync.Log on its own thread.)
# ============================================================================
$Worker = {
    function Log($m) { $Sync.Log.Enqueue([string]$m) }
    try {
        if ($Sync.Proxy) { $script:PreferredProxy = [string]$Sync.Proxy }
        if ($Sync.Action -eq 'install') {
            $running = @()
            if ($Sync.CloseDiscord) {
                $running = @(Get-DiscordProcesses | ForEach-Object { $_.Name } | Select-Object -Unique)
                Log '正在关闭 Discord...'; Stop-DiscordProcesses
            }
            Log '正在从 GitHub 获取最新插件...'
            if (Update-PayloadCache) {
                $v = $null
                try { $v = Get-PayloadVersion ([System.IO.File]::ReadAllBytes($script:CacheFile)) } catch {}
                if ($v) { Log ('  插件已缓存（v' + $v.ToString() + '）') } else { Log '  插件已缓存' }
            } else {
                $why = if ($script:LastNetError) { '：' + $script:LastNetError } else { '' }
                Log ('  下载失败' + $why + '，将使用已有缓存 / 内置副本')
            }
            $n = 0
            foreach ($i in (Get-DiscordInstalls)) {
                $r = Install-One -Install $i -Force:$Sync.Force
                Log ('  ' + $i.Flavor + ' ' + $i.Version + ' -> ' + $r)
                if ($r -eq 'installed' -or $r -eq 'updated') { $n++ }
            }
            if ($Sync.KeepInjected) {
                $stable = Copy-SelfToStable -SelfPath $Sync.SelfPath
                Log ('开机自动保持注入: ' + (Register-KeepInjected -SelfPath $stable))
            } else { Unregister-KeepInjected; Log '已关闭开机自动保持注入' }
            if ($Sync.CloseDiscord -and $Sync.Relaunch) {
                Log '正在重新启动 Discord...'
                if (-not $running) { $running = @('Discord') }
                foreach ($fl in $running) { Start-Discord -Flavor $fl }
            }
            $Sync.Ok = $true
            $Sync.Summary = ('完成：已注入 / 更新 ' + $n + ' 个 Discord。重启 Discord 后按 Ctrl+Shift+H 打开设置。')
        }
        elseif ($Sync.Action -eq 'uninstall') {
            $running = @()
            if ($Sync.CloseDiscord) {
                $running = @(Get-DiscordProcesses | ForEach-Object { $_.Name } | Select-Object -Unique)
                Log '正在关闭 Discord...'; Stop-DiscordProcesses
            }
            $n = 0
            foreach ($i in (Get-DiscordInstalls)) {
                $r = Uninstall-One -Install $i
                Log ('  ' + $i.Flavor + ' -> ' + $r)
                if ($r -eq 'removed') { $n++ }
            }
            Unregister-KeepInjected
            foreach ($d in @($script:AppDataHalcyon, (Join-Path $env:LOCALAPPDATA 'Halcyon'))) {
                try { if (Test-Path -LiteralPath $d) { Remove-Item -LiteralPath $d -Recurse -Force -ErrorAction SilentlyContinue } } catch {}
            }
            if ($Sync.CloseDiscord -and $Sync.Relaunch) {
                Log '正在重新启动 Discord...'
                if (-not $running) { $running = @('Discord') }
                foreach ($fl in $running) { Start-Discord -Flavor $fl }
            }
            $Sync.Ok = $true
            $Sync.Summary = ('完成：已卸载 ' + $n + ' 个。Discord 已恢复原版。')
        }
    } catch {
        $Sync.Ok = $false
        $Sync.Summary = ('出错：' + $_.Exception.Message)
        Log ('ERROR: ' + $_.Exception.Message)
    } finally {
        $Sync.Done = $true
    }
}
# ============================================================================
#  Entry
# ============================================================================
. $Engine

if ($EnsureInjected) { Invoke-EnsureInjected; return }

if ($SelfTest) {
    # Dev/CI check: exercise the engine read-only (no GUI, no injection, no network kill).
    Write-Output ('index.js chars   : ' + $script:ShimIndexJs.Length)
    Write-Output ('preload.js chars : ' + $script:ShimPreloadJs.Length)
    $emb = Get-EmbeddedPayloadBytes
    if ($emb) {
        $head = [System.Text.Encoding]::UTF8.GetString($emb, 0, [Math]::Min(24, $emb.Length))
        Write-Output ('builtin payload  : ' + $emb.Length + ' bytes, head=' + $head)
        $bv = Get-PayloadVersion $emb
        Write-Output ('builtin version  : ' + $(if ($bv) { $bv.ToString() } else { 'unknown' }))
    } else {
        Write-Output 'builtin payload  : MISSING'
    }
    $cacheVer = $(try { $cv = Get-PayloadVersion ([System.IO.File]::ReadAllBytes($script:CacheFile)); if ($cv) { $cv.ToString() } else { 'unknown' } } catch { 'missing' })
    Write-Output ('cache version    : ' + $cacheVer)
    Write-Output ('proxy specs      : ' + ((Get-ProxySpecs) -join ', '))
    if ($env:HALCYON_SELFTEST_NET -eq '1') {
        # Opt-in network probe: shows exactly which mirror x proxy combination
        # works on this machine, and the real error for the ones that don't.
        Write-Output '--- network probe ---'
        foreach ($u in $script:PayloadUrls) {
            foreach ($s in (Get-ProxySpecs)) {
                $script:LastNetError = $null
                $probe = Invoke-PayloadDownload -Url $u -ProxySpec $s
                if (Test-PayloadBytes $probe) {
                    $pv = Get-PayloadVersion $probe
                    Write-Output ('OK   ' + $s + '  ' + $u + '  v' + $(if ($pv) { $pv.ToString() } else { '?' }))
                    break
                }
                Write-Output ('FAIL ' + $s + '  ' + $u + '  ' + $(if ($script:LastNetError) { $script:LastNetError } else { 'invalid body' }))
            }
        }
    }
    Write-Output ('index line 1     : ' + (($script:ShimIndexJs -split "`n")[0]).Trim())
    Write-Output ('preload line 1   : ' + (($script:ShimPreloadJs -split "`n")[0]).Trim())
    $installs = @(Get-DiscordInstalls)
    Write-Output ('discord installs : ' + $installs.Count)
    foreach ($i in $installs) { Write-Output ('  - ' + $i.Flavor + ' ' + $i.Version + ' injected=' + $i.Injected) }
    Write-Output ('diagnostics      : ' + (Get-Diagnostics))
    $tmp = Join-Path $env:TEMP 'halcyon_selftest_index.js'
    Write-Utf8NoBom -Path $tmp -Content $script:ShimIndexJs
    $b = [System.IO.File]::ReadAllBytes($tmp)
    $hasBom = ($b.Length -ge 3 -and $b[0] -eq 0xEF -and $b[1] -eq 0xBB -and $b[2] -eq 0xBF)
    Write-Output ('no-bom write OK  : ' + (-not $hasBom))
    Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
    return
}

