# DPI awareness MUST be set before any WinForms type is loaded (ps2exe ships no
# app.manifest), or the UI renders blurry on scaled displays.
try {
    Add-Type -ErrorAction SilentlyContinue -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class HcDpi {
    [DllImport("shcore.dll")] public static extern int SetProcessDpiAwareness(int value);
    [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
}
"@
    try { [HcDpi]::SetProcessDpiAwareness(1) | Out-Null } catch { try { [HcDpi]::SetProcessDPIAware() | Out-Null } catch {} }
} catch {}

